<!doctype html><html lang="sr"><head><meta charset="utf-8"><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;color:#1f2937;font-family:DejaVu Sans Mono,monospace;font-size:8pt}.p{padding:14mm 16mm 18mm}.top{padding:8mm;background:#f8fafc;border:1px solid #cbd5e1}.tag{color:#16a34a;font-weight:bold}.h{margin:4px 0;font-family:DejaVu Sans,sans-serif;font-size:18pt;font-weight:bold}.t,.items,.sum{width:100%;border-collapse:collapse}.t{margin:7mm 0}.t td{width:50%;padding:7px;vertical-align:top;border:1px solid #dbe4ea}.mute{color:#64748b}.items th{padding:6px;background:#f1f5f9;text-align:left}.items td{padding:7px;border-bottom:1px solid #dbe4ea;vertical-align:top}.add{background:#f0fdf4}.r{text-align:right}.sum{width:44%;margin:7mm 0 0 auto;border:1px solid #86efac}.sum td{padding:6px;border-top:1px solid #bbf7d0}.sum td:last-child{text-align:right;font-weight:bold}.total td{background:#16a34a;color:#fff;font-size:11pt}.box{margin-top:7mm;padding:7px;border-left:3px solid #16a34a;background:#f0fdf4;white-space:pre-line}.foot{position:fixed;bottom:7mm;left:16mm;color:#94a3b8;font-size:6pt}</style></head><body><div class="p"><div class="top"><div class="tag">diff -- račun/{{ $invoice->invoice_number }}</div><div class="h">{{ $company->name }}</div><div class="mute">{{ $company->address }} · {{ $company->city }} &nbsp; | &nbsp; {{ $invoice->date?->format('d.m.Y.') }}</div></div><table class="t"><tr><td><span class="tag">+ kupac</span><br><strong>{{ $invoice->client?->name }}</strong><br><span class="mute">{{ $invoice->client?->address }}<br>{{ $invoice->client?->city }}</span></td><td><span class="tag">+ plaćanje</span><br>rok: {{ $invoice->due_date?->format('d.m.Y.') }}<br>način: {{ $invoice->payment_type?->label() }}<br>valuta: {{ $invoice->currency }}</td></tr></table><table class="items"><thead><tr><th>promjena</th><th>stavka</th><th class="r">količina</th><th class="r">iznos</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr class="add"><td class="tag">+</td><td><strong>{{ $item->name }}</strong></td><td class="r">{{ $item->quantity }} {{ $item->unit?->value }}</td><td class="r">{{ $f($item->total) }} {{ $c }}</td></tr>@endforeach</tbody></table><table class="sum"><tr><td>osnovica</td><td>{{ $f($invoice->subtotal) }} {{ $c }}</td></tr>@if($vat)<tr><td>pdv</td><td>{{ $f($invoice->tax_total) }} {{ $c }}</td></tr>@endif<tr class="total"><td>MERGED ✓</td><td>{{ $f($invoice->total) }} {{ $c }}</td></tr></table>@if($invoice->notes)<div class="box">+ napomena<br>{{ $invoice->notes }}</div>@endif</div><div class="foot">git diff --stat · račun potvrđen</div></body></html>
